def capacity_predecessor_source(relative,raw):
    raw=fixture_initializer_predecessor_source(relative,raw)
    raw=capacity_successor_source(relative,raw)
    row=CAPACITY_SOURCE_RECORDS.get(relative)
    if row is None or hashlib.sha256(raw.replace(b'\r\n',b'\n')).hexdigest()!=row['after_sha256']:
        return raw
    z=zlib.decompressobj();value=z.decompress(base64.b85decode(row['compressed']),8*1024*1024+1)
    identity=hashlib.sha1(b'blob '+str(len(value)).encode()+b'\0'+value).hexdigest()
    if not (z.eof and not z.unused_data and len(value)==row['bytes']<=8*1024*1024
            and hashlib.sha256(value).hexdigest()==row['before_sha256'] and identity==row['before_git_blob']):
        raise ValueError('CI_CAPACITY_AUTHENTICATED_PREDECESSOR_CHANGED')
    return value


